contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount is the Ether amount this test will deposit into c before calling withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // perform a deposit of depositAmount into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // observe contract Ether balance before withdraw
        uint beforeContractBalance = address(c).balance;

        // call withdrawAll and catch whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe contract Ether balance after withdraw
        uint afterContractBalance = address(c).balance;

        // There's no public getter for the mapping 'credit' despite its declaration; however, its observable effect is on contract balance and on whether further withdraws can succeed without additional deposits.
        // General rule: if withdrawAll did not revert then (1) the contract's balance did not increase, and (2) the contract's balance decreased by at most the amount it had before the withdraw (i.e., non-negative), and (3) after a successful withdraw the contract's balance is <= beforeContractBalance.
        // These conditions express that withdrawAll cannot create Ether out of thin air and cannot increase C's balance when it succeeds.
        assert(reverted || (afterContractBalance <= beforeContractBalance && beforeContractBalance - afterContractBalance <= beforeContractBalance));
    }

    // allow receiving Ether
    receive() external payable {}
}

